DELETE FROM public.story_entry_points WHERE sid IN (source_story_id,target_story_id);
DELETE FROM public.stories WHERE id=sid;
DELETE FROM public.periods WHERE id IN ('bca1b165-97dc-47ae-8ed3-bbdd6de23c2d','6e520a59-415f-44a2-b16f-8f17bf182d8d','1f243925-d9e1-45c6-a339-ed17788503bc','f462aee0-b25a-4834-93a5-a7b126b41b37','dabec932-310a-48f0-993a-48cb4a699290','7930a98f-855b-43f1-a36b-207fc2151cb7','8cbd5fb1-770b-4050-9239-9adc5793668b');
DELETE FROM public.events WHERE id IN ('b3c18bcf-1a71-4998-be68-8ace532fd1a5','c9ece010-aa3c-496d-bd74-36c47f0a8db9','413b49a3-843d-4242-9f94-91903d776c83','48e7c921-01e0-4614-abf7-9083770c2122','c5a88fe4-e636-4e56-a8a5-4a6274b8717c','dc39b629-8437-4a0c-bbf6-520bab52e224','efb6c831-6661-4773-9855-8898cecf8296','6625b495-b3dd-43da-b2ba-da9fb3f4d23b','ea326271-1565-4a50-a356-8fac84071096','cebf4ae7-6b5b-49ef-ac33-589d16cfb00e','d970fa29-fe77-4cee-ac33-7883b4a9264f','c8baa690-4af2-486d-9209-8a6bed407fe5','1db9e518-b75f-40e4-9c77-4f1989d672d2','092e4d1a-8013-48d1-9068-7bd2aaa56206','1ca03781-8c2d-4f6a-8fb9-1ae54db97e41','03efea30-7762-4564-b986-822fd4d0b556','164d4aa6-6cda-4081-98f3-1e8487710ed7','f415bdd8-8020-49af-a813-ed95a6104375','c458a733-5849-4fbd-8abd-718ae95e494e','6d8e042a-518b-4b00-a625-6435204b680c','2cd0aaca-ebba-47fc-aadf-f5fcbf93d23d','8c177b6d-db5c-4eaf-851b-73c1dd7f930d','b5b90b83-eecb-4073-b2bf-4f2062e833b0','1049c24d-bf78-453e-b7a1-6a295a312cda','4ee053c5-9e7c-4760-a563-a72dd4a4d259','a635eed2-b1ee-41ec-9c12-cd2c74573334');
